/**
 * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
 * @param <V> the graph vertex type
 * @param <E> the graph edge type
 * @return a mapping from graph to graph
 */
public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Create a new, empty mapping
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>();

    // Add each vertex of the graph to the mapping, with itself as the corresponding value
    for (V vertex : graph.getVertices()) {
        mapping.addVertex(vertex, vertex);
    }

    return mapping;
}
