@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap){
    // Initialize a new empty graph with 2 vertex sets
    Graph<V, E> graph = new Graph<V, E>(2);

    // Loop through each vertex in the result map
    for(Entry<String, V> entry : resultMap.entrySet()){
        // Check if the vertex is in the first or second set
        if(entry.getKey().startsWith("A")){
            // If it's in the first set, add it to the first vertex set
            graph.addVertex(0, entry.getValue());
        } else {
            // If it's in the second set, add it to the second vertex set
            graph.addVertex(1, entry.getValue());
        }
    }

    // Loop through each vertex in the first set and connect it to each vertex in the second set
    for(int i = 0; i < graph.getNumVertices(0); i++){
        for(int j = 0; j < graph.getNumVertices(1); j++){
            // Add an edge from the first vertex to the second vertex
            graph.addEdge(i, j, new E("A", graph.getVertex(i), graph.getVertex(j)));
        }
    }

    // Set the target graph to the constructed graph
    target = graph;
}

