/**
 * Checks if a String ends with a specified suffix (optionally case insensitive).
 *
 * This method is a copy of String.endsWith(String) with the additional ability of ignoring case during the comparison.
 *
 * @param str the String to check, may be null
 * @param suffix the suffix to find, may be null
 * @param ignoreCase indicates whether the compare should ignore case (case insensitive) or not.
 * @return <code>true</code> if the String starts with the prefix or both <code>null</code>
 */
private static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == null && suffix == null;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    int strOffset = strLen - suffixLen;
    return str.regionMatches(ignoreCase, strOffset, suffix, 0, suffixLen);
}

