/**
* Returns a prime number which is >= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity >= 1000).
* @param desiredCapacity the capacity desired by the user.
* @return the capacity which should be used for a hashtable.
*/
public static int nextPrime(int desiredCapacity) {
    // If the desired capacity is less than 1000, use 11% as the margin for error
    if (desiredCapacity < 1000)
        return nextPrime(Math.round(desiredCapacity * 1.1));

    // Otherwise, use 11% as the margin for error and make sure the result is at least 1000
    return Math.max(nextPrime(Math.round(desiredCapacity * 1.1)), 1000);
}

// Finds the next prime greater than or equal to the specified number.
private static int nextPrime(int n) {
    if (n < 3)
        return n;

    // If n is already prime, its next prime is greater
    if (n % 2 != 0 && n % 3 != 0)
        return n + 2;

    // Skip composite numbers
    if (n < 5 || n % 5 != 0)
        n += 2;
    else
        n += 4;

    // If n is a multiple of 5, add 2 to skip its prime deficiency
    if (n % 5 == 0)
        n += 2;

    // Determine the next prime by repeatedly dividing by 2 or 3 and incrementing n by 2
    while (true) {
        boolean isPrime = true;
        if (n % 2 == 0) {
            isPrime = false;
            n /= 2;
        } else if (n % 3 == 0) {
            isPrime = false;
            n /= 3;
        } else {
            break;
        }
    }
    return n;
}

