import static org.apache.commons.io.FilenameUtils.WINDOWS_SEPARATOR;

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int loc0 = indexOfLastSeparator(filename);
    if (loc0 == -1) {
        return -1;
    }

    // check that there is no directory separator after the last dot
    char[] chars = filename.toCharArray();
    for (int i = loc0 + 1; i < chars.length; i++) {
        if (chars[i] == EXTENSION_SEPARATOR || chars[i] == WINDOWS_SEPARATOR) {
            return -1;
        }
    }

    return loc0 + 1;
}
